import csv,os
os.chdir(os.path.expanduser('~/kinship-cases/sokolov'))
def rd(f):
    with open(f) as fh: r=csv.DictReader(fh); return r.fieldnames,list(r)
def wr(f,h,rows):
    with open(f,'w',newline='') as fh: w=csv.DictWriter(fh,fieldnames=h); w.writeheader(); w.writerows(rows)
def add(f,items):
    h,rows=rd(f); ids={r[h[0]] for r in rows}
    for it in items:
        if it[0] in ids: continue
        rows.append(dict(zip(h,it+['']*(len(h)-len(it)))))
    wr(f,h,rows)
